def encode_cyclic(s: str) -> str:
    """
    Returns encoded string by cycling groups of three characters.
    """
    # Split the string into groups of 3 (last group may be shorter)
    groups = [s[i*3:(i+1)*3] for i in range((len(s) + 2) // 3)]
    # For each full group of 3, rotate left by 1 (move first char to end)
    encoded_groups = []
    for group in groups:
        if len(group) == 3:
            encoded_groups.append(group[1] + group[2] + group[0])
        else:
            encoded_groups.append(group)
    return ''.join(encoded_groups)


def decode_cyclic(s: str) -> str:
    """
    Decodes a string that was encoded with encode_cyclic.
    """
    # Each 3-character group was rotated left by 1 (x y z -> y z x)
    # To decode, rotate right by 1 (or left by 2)
    groups = [s[i*3:(i+1)*3] for i in range((len(s) + 2) // 3)]
    decoded_chars = []
    for group in groups:
        if len(group) == 3:
            # Rotate right by 1: last char to front
            decoded_chars.append(group[-1] + group[:-1])
        else:
            decoded_chars.append(group)
    return ''.join(decoded_chars)
