import math

def prime_fib(n: int):
    """
    Returns the n-th number that is both a Fibonacci number and a prime.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(math.isqrt(num))
        for i in range(3, limit + 1, 2):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1  # Starting Fibonacci numbers
    count = 0
    while True:
        a, b = b, a + b  # Move to the next Fibonacci number
        if is_prime(a):
            count += 1
            if count == n:
                return a
