import math

def is_multiply_prime(a):
    """
    Returns True if the given integer a (where a < 100) is the product of exactly three prime numbers
    (not necessarily distinct), otherwise False.
    """
    if a < 2:
        return False

    # Generate all primes up to a (since the largest prime factor in a product of three primes
    # will be at most a when the others are 2)
    def sieve(n):
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False
        return [i for i, val in enumerate(is_prime) if val]

    primes = sieve(a)

    # Check all combinations of three primes whose product equals a
    # (since a < 100, we can use nested loops without performance issues)
    npr = len(primes)
    for i in range(npr):
        p1 = primes[i]
        if p1 > a:
            break  # further p1 will only be larger
        for j in range(i, npr):
            p2 = primes[j]
            if p1 * p2 > a:
                break  # even with p3=2, product too big
            for k in range(j, npr):
                p3 = primes[k]
                product = p1 * p2 * p3
                if product == a:
                    return True
                if product > a:
                    break  # p3 increasing will only make it bigger
        # Early break if p1^3 > a (impossible to get three same or larger primes)
        if p1 * p1 * p1 > a:
            break
    return False
